-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('sovietski-firebird-heavy-machine', 'Sovietski Firebird Heavy Machine', 'rifts', 'borg', 'One human volunteer (full conversion).', 'None.', 'Running: 70 mph (112 km) maximum wearing the Firebird flight system, 100 mph (160 km) without it. Leaping: 15 feet (4.6 m) high or 25 feet (7.6 m) lengthwise unassisted, +50% with a running start. Flight-pack assisted leaps reach 100 feet (30.5 m) high and 200 feet (61 m) across without true flight; the foot and lower-leg thrusters alone manage a third of that, 30 feet (9.1 m) high and 60 feet (18.3 m) across.', 'With the flight pack: 200 mph (320 km), cruising 80 mph (128 km); an overdrive burst reaches 350 mph (560 km) for 1D4 minutes. Ceiling 5,000 feet (1,524 m). Range effectively unlimited (the pack has its own power), but its jets must cool after six hours of nonstop flight, or the cyborg rests or walks 20 minutes in every two hours. Without the pack the leg and foot thrusters let it rise and hover up to 100 feet (30.5 m) for 1D4+1 minutes before it drifts back down.', 'Swims 15 mph (24 km); with an oxygen storage cell it walks along the floor of a river, lake or shallow sea at 8 mph (13 km). Maximum depth 800 feet (244 m).', 'Height 9 feet (2.7 m); width 4 feet (1.2 m) wings folded, 14 feet (4.3 m) wings spread, 3 feet, 7 inches (1.1 m) at the shoulders without the flight pack; length 5 feet (1.5 m) with the flight pack, 3 feet (0.9 m) without.', '1,100 pounds (495 kg) without flight pack and armor; 1.2 tons with them.', 240, 1, NULL, 3700000, 'Sovietski cost 3.7 million credits; 6.3 million credits on the Black Market, rare. The Sovietski figure is stored.', 'The Sovietski''s flying Heavy Machine, doing the job other armies give to light flying power armor such as the CS SAMAS. It was built to fight Gargoyles and Warlord Wingriders. Besides a detachable back-mounted flight pack with wings and one big central thruster (air intakes over each shoulder), it has boosters in the feet and lower legs, which serve for boosted jumps, high-altitude drops from aircraft, silent glides, and loud jet-driven attacks launched from city rooftops or mountainsides. An overdrive mode turns it briefly into a man-shaped rocket at the cost of control, so its pilots train hard to avoid collisions; the glow of its jets and weapons gave it the name of the Russian fire bird. The pack draws on the cyborg''s own nuclear supply and carries no power or steering jets of its own, so a stolen one is of little use: any other cyborg fitted with it is -20% to Pilot: Jet Pack. The Firebird can shed the pack at will to enter buildings or tight spaces, and a stowed pack linked to it lifts off the ground to meet the cyborg and relock when it returns. Robot P.S. 32 and Robot P.P. 22: 1D4 M.D. restrained punch, 2D4 M.D. full punch, 4D4 M.D. power punch, 2D4 M.D. kick, 2D8 M.D. leap kick (power punch and leap kick each use two attacks). Bonuses: one extra attack per melee, initiative +1, strike, parry and dodge +4, pull punch +2. Penalties: -4 to strike, parry, disarm and pull punch during an overdrive burst; -40% to Prowl, and with tactile sensitivity of 35%, -40% to Forgery, Picking Locks, Picking Pockets, surgery, Whittling/Sculpting, Art and any fine-fingered skill. Nuclear, 20-year average life. Bionic features: every standard Sovietski Heavy Machine feature, plus a super-telescopic eye, radar sensor, speedometer and built-in loudspeaker. Starting weapons and features: one weapon and one feature of choice per hand, one leg compartment and one weapon rod per leg, a face (most keep a youthful version of their own), two more eye or head features, and Micro-Repair Robots or a Cyber-Nano-Robot Repair System for field repairs. Its heavy Firebird armor and helmet add 80 M.D.C. to the head; the main body figure is printed as +210 in the M.D.C. table and its note, and as 240 in the weapon systems list. Chop-shops, Warlord camps, Mindwerks and some mercenaries will fit these systems to Shocktroopers or Heavy Machines for a price.', 'Rifts World Book 36: Sovietski p.134-136'),
  ('sovietski-whirlwind-heavy-machine', 'Sovietski Whirlwind Heavy Machine', 'rifts', 'borg', 'One human volunteer (full conversion).', 'None.', 'Running: 100 mph (160 km) maximum. Motorcycle mode: 280 mph (448 km) maximum, 160 mph (256 km) off-road, cruising 60 mph (96 km); range effectively unlimited. Leaping: 15 feet (4.6 m) high or 25 feet (7.6 m) lengthwise, +50% with a running start; motorcycle jumps vary with the ground, up to 50 feet (15.2 m) high and 130 feet (39.6 m) across from a fast start and a good ramp.', 'None. It cannot take Cyberjet Nodes or a jet pack; the motorcycle system takes their place.', 'Swims about 15 mph (24 km); with an oxygen storage cell it walks the bottom of rivers and waterways at about half that. Maximum depth 800 feet (244 m).', 'Height 7 feet (2.1 m) to the top of the head, 9 feet (2.7 m) counting the back-mounted wheel, 4 feet, 6 inches (1.4 m) in motorcycle mode; width 2 feet, 6 inches (0.8 m) in either mode; length 5 feet, 6 inches (1.7 m) in motorcycle mode.', '1,500 pounds (675 kg).', 200, 1, NULL, 5400000, 'Sovietski cost 5.4 million credits; 7+ million credits on the Black Market, rare. The Sovietski figure is stored.', 'The most unconventional Sovietski cyborg of any class: a four-armed Heavy Machine that folds into its own motorcycle, built for city fighting and fast emergency response and just as at home with light motorized infantry. Standing, its narrow shoulders, thin legs, extra arms and the two spokeless all-terrain wheels rising from its back like wings give it an insect-like look. To ride, one back wheel on a light frame swings down between its legs as it sits, with a handle gripped by a lower arm, and the other locks in between its feet, the legs locking too. Long training makes the cyborg a stunt-capable rider who leans and shifts its weight like a biker, keeping the upper arms free to shoot built-in or handheld weapons (energy pistols and submachine-guns are preferred at speed) or to use the forearm Vibro-Blades on infantry. Robot P.S. 32 and Robot P.P. 22: 1D4 M.D. restrained punch, 2D4 M.D. full punch, 4D4 M.D. power punch, 2D4 M.D. kick, 2D8 M.D. leap kick (power punch and leap kick each use two attacks). Bonuses: W.P. Paired Weapons, two extra attacks per melee for the four arms, +15% to Climbing, initiative +2, strike, parry and dodge +4, entangle +1, pull punch +2, and half the usual penalties for stunt driving, evasive maneuvers, burst and wild shooting. Penalties: tactile sensitivity 50%, -30% to Prowl and -25% to Forgery, Pick Locks, Pick Pockets, surgery, Whittling/Sculpting, Art and any fine-fingered skill. Its slim build and human-sized hands let it use any human or Light Machine weapon or tool, and it is strong enough for most Heavy Machine weapons. Heavy Whirlwind armor and helmet give the main body +180 M.D.C. and the head +80, with a -15% skill penalty while worn. Nuclear, 20-year average life. Bionic features: every standard Sovietski Heavy Machine feature, plus quick draw holsters (two on the legs, two on the upper torso), wide-angle vision and Spectra-Eye, a speedometer and a built-in loudspeaker. Starting weapons and features: one weapon and one feature of choice per hand, one leg compartment and one weapon rod per leg, a face (usually its own, hidden by the helmet in combat), three more eye or head features, and two Micro-Repair Robots or a Cyber-Nano-Robot Repair System. Chop-shops, Warlord camps, Mindwerks and some mercenaries will fit these systems to Shocktroopers or Heavy Machines for a price.', 'Rifts World Book 36: Sovietski p.136-138');

