INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('sovietski-firebird-heavy-machine', 1, 'Palm Plasma Flamethrower (1)', '5D6 M.D. to the target and anyone in the blast''s path', 1, '100 feet (30.5 m)', 'Each blast counts as one melee attack.', 'Seven blasts; refueled with military grade napalm at base.', NULL, 'Anti-personnel. Left arm, fed from an internal tank; the item heading puts the nozzle in the palm, the M.D.C. table under the left wrist.'),
  ('sovietski-firebird-heavy-machine', 2, 'Extendible Forearm Vibro-Sword (1)', '3D6 M.D. per strike (Robot P.S. damage included)', 1, 'Melee combat.', NULL, 'Effectively unlimited.', NULL, 'Right forearm; extends and retracts. Suited to parrying claws.'),
  ('sovietski-firebird-heavy-machine', 3, 'Forearm Lasers (2)', '3D6 M.D. single blast, or 6D6 M.D. when both arms fire at the same target', 1, '2,000 feet (610 m)', 'Each single or dual blast counts as one melee attack.', 'Effectively unlimited; tied to the cyborg''s nuclear power supply.', NULL, 'Defense. One low-profile laser per forearm, used when rail gun and flamethrower ammunition runs low.'),
  ('sovietski-firebird-heavy-machine', 4, 'Wing Mini-Missiles (3 per wing)', 'Varies by missile: typically Plasma 1D6x10 M.D. (15 foot/4.6 m radius), Armor Piercing 1D4x10 M.D. (3 foot/0.9 m radius) or High Explosive 5D6 M.D. (5 foot/1.5 m radius); usually loaded as Plasma and High Explosive together', 1, 'One mile (1.6 km)', 'One at a time or in volleys of 2 or 4.', 'Six, three per wing.', NULL, 'Assault, against air and hardened ground targets. Carried on wing hard points.'),
  ('sovietski-firebird-heavy-machine', 5, 'Clawed Feet (2)', '+2D4 M.D. to kicks; a flying rake does 4D6 M.D. (Robot P.S. damage included)', 1, 'Melee: kicks and aerial strikes.', NULL, 'Unlimited.', NULL, 'Assault. Vibro-Blade claws in both feet.'),
  ('sovietski-firebird-heavy-machine', 6, 'AK-347B Cyborg Kalashnikov Rail Gun', '2D6 M.D. single shot, or 1D6x10 M.D. for a 10 round burst', 1, '4,000 feet (914 m) as printed', 'Each single shot or burst counts as one attack.', '200 and 400 round magazines, or a 2,000 round detachable drum; cut off from the cyborg''s power or an E-Pack, its internal battery powers 10 bursts.', NULL, 'Handheld, standard issue; the Firebird may carry any weapon a Heavy Machine can handle. Belt fed from a drum on the hip or back; shaped like an outsized AK47.'),
  ('sovietski-whirlwind-heavy-machine', 1, 'Forearm Ion Blasters (2)', '4D6 M.D. single blast, or 1D4x10 M.D. when both arms fire at the same target', 1, '1,200 feet (366 m)', 'Each single or dual blast counts as one melee attack.', 'Effectively unlimited; tied to the cyborg''s nuclear power supply.', NULL, 'Assault. One low-profile blaster in each upper forearm.'),
  ('sovietski-whirlwind-heavy-machine', 2, 'Forearm Vibro-Blades (2)', '2D6 M.D. per strike; 2D6+8 M.D. when traveling over 50 mph (80 km)', 1, 'Melee.', NULL, NULL, NULL, 'Close combat. One in each upper forearm.'),
  ('sovietski-whirlwind-heavy-machine', 3, 'Forearm Lasers (2)', '2D6 M.D. single blast, or 4D6 M.D. when both arms fire at the same target', 1, '2,000 feet (610 m)', 'Each single or dual blast counts as one melee attack.', 'Effectively unlimited; tied to the cyborg''s nuclear power supply.', NULL, 'Assault. One low-profile laser in each lower forearm.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 machines are in' AS assertion, count(*) AS got, 2 AS want
  FROM vehicles WHERE slug IN ('sovietski-firebird-heavy-machine', 'sovietski-whirlwind-heavy-machine');
SELECT 'their 20 locations are in' AS assertion, count(*) AS got, 20 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('sovietski-firebird-heavy-machine', 'sovietski-whirlwind-heavy-machine');
SELECT 'their 9 weapon entries are in' AS assertion, count(*) AS got, 9 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('sovietski-firebird-heavy-machine', 'sovietski-whirlwind-heavy-machine');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('sovietski-firebird-heavy-machine', 'sovietski-whirlwind-heavy-machine') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

